const canvas=document.querySelector('#void');const ctx=canvas?.getContext('2d',{alpha:true});let w=innerWidth,h=innerHeight,dpr=1,mouse={x:.72,y:.28},points=[];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function resize(){if(!canvas)return;dpr=Math.min(devicePixelRatio||1,2);w=innerWidth;h=innerHeight;canvas.width=w*dpr;canvas.height=h*dpr;canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(dpr,0,0,dpr,0,0);const n=Math.min(86,Math.max(28,Math.floor(w/18)));points=Array.from({length:n},(_,i)=>({a:i/n*Math.PI*2,r:90+Math.random()*Math.min(w,h)*.42,z:Math.random(),s:.08+Math.random()*.22}))}
function draw(t=0){if(!ctx)return;ctx.clearRect(0,0,w,h);const cx=w*mouse.x,cy=h*mouse.y;for(const p of points){const a=p.a+t*.00004*p.s;const squash=.28+.18*p.z;const x=cx+Math.cos(a)*p.r,y=cy+Math.sin(a)*p.r*squash;ctx.beginPath();ctx.arc(x,y,.5+1.2*p.z,0,Math.PI*2);ctx.fillStyle=`rgba(${p.z>.5?'32,230,210':'141,107,255'},${.08+.22*p.z})`;ctx.fill()}if(!reduced)requestAnimationFrame(draw)}
addEventListener('resize',resize,{passive:true});if(canvas)addEventListener('pointermove',e=>{mouse.x=.65+(e.clientX/w-.5)*.08;mouse.y=.3+(e.clientY/h-.5)*.06},{passive:true});resize();draw();
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.14});document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
const copyButton=document.querySelector('#copy');if(copyButton)copyButton.addEventListener('click',async e=>{const text=document.querySelector('pre').innerText;try{await navigator.clipboard.writeText(text);e.currentTarget.textContent='已复制';setTimeout(()=>e.currentTarget.textContent='复制',1400)}catch{e.currentTarget.textContent='复制失败'}});
const space=document.querySelector('.space-ui');if(space&&!reduced){addEventListener('pointermove',e=>{const rx=(e.clientY/innerHeight-.5)*-5,ry=(e.clientX/innerWidth-.5)*7;space.style.transform=`rotateX(${rx}deg) rotateY(${ry}deg)`},{passive:true});addEventListener('scroll',()=>{const z=Math.min(scrollY*.08,70);space.style.translate=`0 ${scrollY*.045}px ${z}px`;space.style.opacity=String(Math.max(.15,1-scrollY/900))},{passive:true})}
